  "knowledge": "NoiseDb (Noise Level)",
  "description": "Illustrates the impact of noise levels in point cloud data on feature recognition accuracy.",
  "definition": "Measured in decibels, representing signal-to-noise ratio in scan data. Values below 1.0 indicate clean data suitable for detailed analysis, while values above 3.0 suggest significant noise that may obscure small features and introduce measurement uncertainty."
}

{
  "id": 20,
  "knowledge": "ScanResolMm (Scan Resolution)",
  "description": "Illustrates the significance of scan resolution measurements in archaeological scanning for feature detection.",
  "definition": "Measured in millimeters, representing the smallest feature that can be distinguished in the scan. Values like 0.5mm enable documentation of fine tool marks on artifacts, while 2.0mm might only capture general shape and macroscopic features."
}

{
  "id": 21,
  "knowledge": "PointDense (Point Density)",
  "description": "Illustrates the significance of point density in archaeological point clouds for information richness.",
  "definition": "Measured as points per square meter. Values around 100 capture basic site topography, 1,000 can document structural details, while 10,000+ enables analysis of surface textures and fine engravings across multiple scales of inquiry."
}

{
  "id": 23,
  "knowledge": "CoverPct (Coverage Percentage)",
  "description": "Illustrates the significance of coverage percentage in archaeological scans for site completeness assessment.",
  "definition": "Percentage of target area successfully captured in scan data. Values above 95% indicate near-complete documentation, while 80% might have significant gaps requiring additional scanning or interpolation methods for comprehensive site analysis."
}

